  "Now": { ca: "Ara", es: "Ahora" },
  "Click to load": { ca: "Clica per carregar", es: "Clic para cargar" },
  "This is one possible solution. Ctrl Z brings your work back.": { ca: "Aquesta és una solució possible. Ctrl Z recupera la teva feina.", es: "Esta es una solución posible. Ctrl Z recupera tu trabajo." },
  "INTERACTIVE STUDIES / 16": { ca: "ESTUDIS INTERACTIUS / 16", es: "ESTUDIOS INTERACTIVOS / 16" },
  "Same squares, <span>same sharpness.</span>": { ca: "Quadres iguals, <span>nitidesa igual.</span>", es: "Cuadros iguales, <span>nitidez igual.</span>" },
  "<strong>Texel density</strong> is how many pixels of texture cover one metre of surface. See it with a <strong>checker map</strong>, compute it in <strong>px/m</strong>, match it with <strong>S</strong>, <strong>Average Islands Scale</strong>, <strong>Pack Islands</strong> and <strong>Set TD</strong> as in Blender, choose a target from the <strong>camera</strong> and the <strong>memory</strong>, and learn when to break the rule.": { ca: "La <strong>texel density</strong> és quants píxels de textura cobreixen un metre de superfície. Mira-la amb un <strong>mapa de quadres</strong>, calcula-la en <strong>px/m</strong>, iguala-la amb <strong>S</strong>, <strong>Average Islands Scale</strong>, <strong>Pack Islands</strong> i <strong>Set TD</strong> com a Blender, tria un objectiu a partir de la <strong>càmera</strong> i de la <strong>memòria</strong>, i aprèn quan cal trencar la regla.", es: "La <strong>texel density</strong> es cuántos píxeles de textura cubren un metro de superficie. Mírala con un <strong>mapa de cuadros</strong>, calcúlala en <strong>px/m</strong>, iguálala con <strong>S</strong>, <strong>Average Islands Scale</strong>, <strong>Pack Islands</strong> y <strong>Set TD</strong> como en Blender, elige un objetivo a partir de la <strong>cámara</strong> y de la <strong>memoria</strong>, y aprende cuándo romper la regla." },
  "Shading": { ca: "Shading", es: "Shading" },
  "LMB select · Shift add · G S R · Wheel zoom · MMB pan": { ca: "LMB seleccionar · Shift afegir · G S R · Roda zoom · MMB desplaçar", es: "LMB seleccionar · Shift añadir · G S R · Rueda zoom · MMB desplazar" },
  "LMB select · MMB orbit · Wheel zoom": { ca: "LMB seleccionar · MMB orbitar · Roda zoom", es: "LMB seleccionar · MMB orbitar · Rueda zoom" },
  "Select": { ca: "Seleccionar", es: "Seleccionar" },
